const config = $('⚙️ Config').first().json;
const brand = $('🎨 Brand Kit').first().json;
const styles = $('📋 Style Packs').first().json;
const trigger = $input.first().json;
return [{ json: { ...trigger, _config: config, _brand: brand, _styles: styles } }];

// Build the system prompt and input text from Style Packs + Brand Kit
const item = $input.first().json;
const style = (item.data && item.data.Style) || $('⚙️ Config').first().json.default_style || 'UGC With People';
const extraNotes = (item.data && item.data['Extra Notes']) || '';

const styles = $('📋 Style Packs').first().json;

// === CASTING ROULETTE (75/25 split — decided in code, not by the agent) ===
let castingDirective = '';
if (style === 'UGC With People') {
  const roll = Math.random();
  let ethnicity;
  if (roll < 0.75) {
    const euro = ['Eastern European / Slavic', 'Mediterranean (Italian, Spanish, Greek)', 'Northern European', 'Central European (German, Austrian)', 'Romanian / Balkan'];
    ethnicity = euro[Math.floor(Math.random() * euro.length)];
  } else {
    const others = ['Latina (Mexican, Brazilian, Colombian)', 'Black (African-American or Afro-Caribbean)', 'East Asian (Korean, Japanese, Chinese)', 'South Asian (Indian, Pakistani)', 'Middle Eastern / North African', 'Southeast Asian (Filipino, Thai)', 'Mixed heritage'];
    ethnicity = others[Math.floor(Math.random() * others.length)];
  }
  const ages = ['22', '24', '26', '28', '31', '34', '37'];
  const age = ages[Math.floor(Math.random() * ages.length)];
  const gender = 'woman';
  castingDirective = `\n\n=== CASTING (LOCKED — use exactly this) ===\nEthnicity: ${ethnicity}\nApproximate age: ${age}\nGender: ${gender}\nThe character in BOTH the image_prompt and video_prompt MUST be a ${age}-year-old ${ethnicity} ${gender}. Describe them with specific matching features (hair color/style, build, clothing) in both prompts so the same person appears in image and video. Face is clearly visible.`;
}

const brand = $('🎨 Brand Kit').first().json;
const trigger = $('Telegram Trigger').first().json;
const ar = $('Analyze Photo').first().json || {};
const photoAnalysis = ar.content || ar.choices?.[0]?.message?.content || ar.message?.content || '';

const rawBrief = trigger?.message?.caption || trigger?.message?.text || '';
const briefMissing = !rawBrief || rawBrief.trim().length < 3;
const userBrief = briefMissing
  ? 'No specific brief — invent a creative direction yourself. Pick a setting, mood, and angle that fits the product category.'
  : rawBrief;

const brandBlock = [];
if (brand.brand_voice) brandBlock.push('Brand voice: ' + brand.brand_voice);
if (brand.target_audience) brandBlock.push('Target audience: ' + brand.target_audience);
if (brand.brand_colors) brandBlock.push('Brand colors: ' + brand.brand_colors);
if (brand.banned_words) brandBlock.push('Avoid these words: ' + brand.banned_words);
if (brand.cta_default) brandBlock.push('Default CTA: ' + brand.cta_default);
const brandInjection = brandBlock.length > 0 ? '\n\n---BRAND KIT---\n' + brandBlock.join('\n') + '\n---END BRAND KIT---\n' : '';

const captionLang = 'English';

const systemPrompt = (styles[style] || styles['Custom']) + brandInjection + castingDirective +
  '\n\nIMPORTANT: Write the caption in ' + captionLang + '. The image_prompt and video_prompt remain in English.' +
  '\n\nCRITICAL: You MUST return ONLY valid JSON with the required fields. NEVER ask the user clarifying questions. NEVER return markdown explanations. If the brief is vague or the product info is sparse, make creative choices yourself based on whatever you have. The workflow expects JSON; anything else breaks it.';

let inputText;
if (style === 'UGC With People') {
  inputText = 'Brief from user: ' + userBrief + '\n\nProduct: ' + photoAnalysis + (extraNotes ? '\n\nExtra notes: ' + extraNotes : '') + '\n\nCreate ONE scene. The casting locked above MUST appear in BOTH the image (face clearly visible, holding/using the product naturally) AND the video (same person, same outfit, same setting, speaking one casual line).';
} else {
  inputText = 'Brief from user: ' + userBrief + '\n\nProduct: ' + photoAnalysis + (extraNotes ? '\n\nExtra notes: ' + extraNotes : '');
}

return [{ json: { _style: style, _systemPrompt: systemPrompt, _inputText: inputText, _captionLang: captionLang } }];

// Robust JSON extraction from agent output
const raw = $input.first().json.output || '';
let jsonStr = raw;

const mdMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
if (mdMatch) jsonStr = mdMatch[1].trim();

if (!jsonStr.trim().startsWith('{')) {
  const objMatch = jsonStr.match(/\{[\s\S]*\}/);
  if (objMatch) jsonStr = objMatch[0];
}

let parsed;
try {
  parsed = JSON.parse(jsonStr);
} catch(e) {
  return [{json: {_parse_failed: true, _raw: raw.substring(0, 800)}}];
}

if (!parsed.image_prompt || !parsed.video_prompt || !parsed.caption) {
  return [{json: {_parse_failed: true, _raw: 'Missing required fields. Got: ' + Object.keys(parsed).join(', ')}}];
}

return [{json: {...parsed, _parse_failed: false}}];

const chatId = String($('Telegram Trigger').first().json.message.chat.id);
const maxRev = $('⚙️ Config').first().json.max_revisions || 3;
const sd = $getWorkflowStaticData('global');
if (!sd.revisions) sd.revisions = {};
sd.revisions[chatId] = (sd.revisions[chatId] || 0) + 1;
const current = sd.revisions[chatId];
return [{ json: { ...$input.first().json, _revision_count: current, _max_reached: current > maxRev } }];

