const raw = $input.first().json.output || '';
let jsonStr = raw;
const mdMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
if (mdMatch) jsonStr = mdMatch[1].trim();
if (!jsonStr.trim().startsWith('{')) {
  const objMatch = jsonStr.match(/\{[\s\S]*\}/);
  if (objMatch) jsonStr = objMatch[0];
}
try {
  return [{json: {...JSON.parse(jsonStr), _parse_failed: false}}];
} catch (e) {
  return [{json: {
    image_prompt: $('Set Prompts').first().json.image_prompt,
    video_prompt: $('Set Prompts').first().json.video_prompt,
    caption: $('Set Prompts').first().json.caption,
    creative_summary: $('Set Prompts').first().json.creative_summary,
    _parse_failed: false
  }}];
}

const style = $('Ask Style').first().json.data.Style;
const imagePrompt = $('Set Prompts').first().json.image_prompt;
const reservation = "Preserve ALL text, labels, logos, and branding on the product EXACTLY as visible in the reference image. Do NOT alter, blur, or distort packaging text. ";

let basePrompt;
if (style === 'UGC With People') {
  basePrompt = reservation +
    "Generate a casual amateur phone photo where a real person is holding, using, or interacting with the product. The HUMAN is the subject of the photo (occupying most of the frame, face clearly visible with a natural expression), with the product clearly visible in their hand, on their skin, or right next to them. Authentic everyday setting, soft natural lighting, slightly uneven framing — looks like a real customer's selfie or casual share, not a posed model shoot. Scene description: " + imagePrompt;
} else {
  basePrompt = reservation + "Place the product in this scenario: " + imagePrompt;
}

return [
  {json: {variant: 1, seed: 100001, _attempts: 0, full_prompt: basePrompt}},
  {json: {variant: 2, seed: 200002, _attempts: 0, full_prompt: basePrompt + " | alternative camera angle and pose"}},
  {json: {variant: 3, seed: 300003, _attempts: 0, full_prompt: basePrompt + " | different lighting and composition"}}
];

