const items = $input.all();
const built = $('Build Variants').all();
return items.map((item, i) => ({
  json: {
    variant: built[i].json.variant,
    seed: built[i].json.seed,
    _attempts: 0,
    taskId: item.json.data.taskId
  }
}));

const carried = $('Carry Task IDs').all();
return $input.all().map(item => {
  const data = item.json.data || {};
  const state = data.state;
  const taskId = data.taskId;
  const meta = carried.find(c => c.json.taskId === taskId) || {json:{}};
  let imageUrl = null;
  if (state === 'success' && data.resultJson) {
    const rj = typeof data.resultJson === 'string' ? JSON.parse(data.resultJson) : data.resultJson;
    imageUrl = rj.resultUrls?.[0];
  }
  return {
    json: {
      variant: meta.json.variant,
      seed: meta.json.seed,
      taskId,
      _state: state,
      _image_url: imageUrl,
      _is_done: state === 'success',
      _is_failed: state === 'fail' || state === 'failed',
      _is_pending: state && state.includes && state.includes('ing')
    }
  };
});

const execId = $execution.id;
const maxAttempts = $('⚙️ Config').first().json.max_poll_iterations || 8;
const sd = $getWorkflowStaticData('node');
if (!sd.var_polls) sd.var_polls = {};

const keys = Object.keys(sd.var_polls);
if (keys.length > 150) keys.slice(0, -150).forEach(k => delete sd.var_polls[k]);

return $input.all().map(item => {
  const key = execId + '_v' + item.json.variant;
  sd.var_polls[key] = (sd.var_polls[key] || 0) + 1;
  const count = sd.var_polls[key];
  return { json: { ...item.json, _attempts: count, _max_reached: count >= maxAttempts } };
});

const execId = $execution.id;
const sd = $getWorkflowStaticData('global');
const key = `varsess_${execId}`;
if (!sd[key]) sd[key] = { urls: {}, started: Date.now() };

// Cleanup any sessions older than 30 min
const now = Date.now();
for (const k of Object.keys(sd)) {
  if (typeof sd[k] === 'object' && sd[k] && sd[k].started && (now - sd[k].started > 30 * 60 * 1000)) {
    delete sd[k];
  }
}

// Store any newly-completed variants from this iteration
for (const item of $input.all()) {
  const v = item.json;
  if (v.variant && v._image_url) {
    sd[key].urls[v.variant] = v._image_url;
  }
}

const stored = sd[key].urls;
const count = Object.keys(stored).length;

// Not all 3 collected yet — kill this branch and wait for the others to arrive
if (count < 3) return [];

// All 3 collected — emit aggregated result and clear state
const result = { urls: [stored[1], stored[2], stored[3]], variants: [1, 2, 3] };
delete sd[key];
return [{ json: result }];

const agg = $input.first().json;
const pairs = (agg.urls || []).map((url, i) => ({ url, variant: (agg.variants || [])[i] || 0 }));
pairs.sort((a, b) => a.variant - b.variant);
const sortedUrls = pairs.map(p => p.url);
const media = sortedUrls.map((url, i) => ({
  type: 'photo',
  media: url,
  caption: i === 0 ? 'Variants 1 / 2 / 3 — pick your favorite below 👇' : ''
}));
return [{json: { media_array: JSON.stringify(media), urls: sortedUrls, variants: pairs.map(p => p.variant) }}];

const data = $input.first().json.data || {};
const videoUrl = data.successFlag === 1 ? data.response?.resultUrls?.[0] : null;
return [{
  json: {
    taskId: data.taskId,
    _videoUrl: videoUrl,
    _is_done: data.successFlag === 1,
    _is_failed: !!data.errorCode,
    _errorMsg: data.errorMessage || ''
  }
}];

const execId = $execution.id;
const maxAttempts = $('⚙️ Config').first().json.max_poll_iterations || 8;
const sd = $getWorkflowStaticData('node');
if (!sd.veo_polls) sd.veo_polls = {};

const keys = Object.keys(sd.veo_polls);
if (keys.length > 100) keys.slice(0, -100).forEach(k => delete sd.veo_polls[k]);

sd.veo_polls[execId] = (sd.veo_polls[execId] || 0) + 1;
const count = sd.veo_polls[execId];

return [{ json: { ...$input.first().json, _attempts: count, _max_reached: count >= maxAttempts } }];

const chatId = String($('Telegram Trigger').first().json.message.chat.id);
const sd = $getWorkflowStaticData('global');
if (sd.revisions) sd.revisions[chatId] = 0;

const sheetIdConfig = $('⚙️ Config').first().json.sheet_id;
return [{
  json: {
    needsCreate: !sheetIdConfig || sheetIdConfig.trim() === '',
    sheetId: sheetIdConfig || '',
    row: [
      new Date().toISOString(),
      $('Telegram Trigger').first().json.message.from.first_name || $('Telegram Trigger').first().json.message.from.username || 'Unknown',
      String($('Telegram Trigger').first().json.message.chat.id),
      $('Ask Style').first().json.data.Style,
      $('Telegram Trigger').first().json.message.caption || $('Telegram Trigger').first().json.message.text || '',
      $('Set Prompts').first().json.image_prompt,
      $('Set Prompts').first().json.video_prompt,
      $('Set Prompts').first().json.caption,
      $('Set Chosen Image').first().json.chosen_image_url,
      $('Process Veo Poll').first().json._videoUrl,
      'Success'
    ]
  }
}];

const newSheetId = $input.first().json.spreadsheetId;
const row = $('Prepare Log').first().json.row;
return [{json: {sheetId: newSheetId, row: row, _notify: true}}];
